using CipherCapsule.Core;
using CipherCapsule.Viewer;
using CipherCapsule.Builder;
using System.Reflection;
using System.Security.AccessControl;
using System.Security.Cryptography;
using System.Security.Principal;
using System.Text.Json;
using System.Diagnostics;
using C=CipherCapsule.Core.Container;
class Inline(Action<CapsuleProgress> f):IProgress<CapsuleProgress>{public void Report(CapsuleProgress p)=>f(p);}
class BatchInline(Action<BatchProgress> f):IProgress<BatchProgress>{public void Report(BatchProgress p)=>f(p);}
class Program{
static string work="",root="";static byte[] pw=Limits.Utf8.GetBytes("Dummy112!Passphrase");static List<object> results=[];
static void Check(bool b){if(!b)throw new Exception("assertion failed");}
static Exception Reject(Action f){try{f();}catch(Exception e){return e;}throw new Exception("expected rejection");}
static string filter=""; static void Test(string name,Action f){if(filter.Length>0&&!name.Contains(filter))return;try{f();results.Add(new{name,passed=true});Console.WriteLine("PASS "+name);}catch(Exception e){results.Add(new{name,passed=false,error=e.ToString()});Console.WriteLine("FAIL "+name+" "+e);}}
static void SetRoot(string r){root=r;typeof(SecureAttachment).GetProperty("TestRoot",BindingFlags.NonPublic|BindingFlags.Static)!.SetValue(null,r);}
static string Next(string n)=>Path.Combine(work,n);
static void Main(string[] args){work=Path.GetFullPath(args[0]);Directory.CreateDirectory(work);if(args.Length>1&&args[1]!="crash")filter=args[1];SetRoot(Next("private"));
if(args.Length>1&&args[1]=="crash"){using var job=SecureAttachment.Create(Next("crash-output"));File.WriteAllText(job.PathName,"DUMMY CRASH PLAINTEXT");File.WriteAllText(Next("ready"),job.PathName);Thread.Sleep(120000);return;}
Test("private ACL owner and user SYSTEM only",()=>{using var j=SecureAttachment.Create(Next("out"));var a=new DirectoryInfo(root).GetAccessControl();Check(a.AreAccessRulesProtected);Check(a.GetAccessRules(true,true,typeof(SecurityIdentifier)).Count==2);j.Finish(null);});
string input=Next("添付 日本語=😀.bin");File.WriteAllBytes(input,Enumerable.Range(0,3*Limits.Chunk+99).Select(i=>(byte)i).ToArray());string zero=Next("empty.txt");File.WriteAllBytes(zero,[]);string package=Next("v2.ccap");
Test("v2 HTML public message and two attachments",()=>{PackageWriter.GenerateCcap(package,"<p>dummy</p>",BodyKind.HTML,[input,zero],pw,true,false,default,checksum256:true,publicMessage:"公開文");using var c=C.Unlock(package,pw,default);Check(c.PublicMessageText=="公開文"&&c.Manifest.Kind==BodyKind.HTML);Check(File.Exists(package+".sha256")&&File.Exists(package+".sha512"));});
using(var c=C.Unlock(package,pw,default)){
Test("multichunk single save content and private final ACL",()=>{c.Save(0,Next("saved.bin"),false,default);Check(SHA256.HashData(File.ReadAllBytes(input)).SequenceEqual(SHA256.HashData(File.ReadAllBytes(Next("saved.bin")))));Check(new FileInfo(Next("saved.bin")).GetAccessControl().GetAccessRules(true,true,typeof(SecurityIdentifier)).Count==2);});
Test("zero byte save",()=>{c.Save(1,Next("empty-saved"),false,default);Check(new FileInfo(Next("empty-saved")).Length==0);});
Test("existing output refuses unapproved overwrite",()=>{File.WriteAllText(Next("keep"),"KEEP");Reject(()=>c.Save(0,Next("keep"),false,default));Check(File.ReadAllText(Next("keep"))=="KEEP");});
Test("approved replacement preserves final content",()=>{c.Save(0,Next("keep"),true,default);Check(new FileInfo(Next("keep")).Length==new FileInfo(input).Length);});
Test("cancel after chunk removes plaintext",()=>{using var ct=new CancellationTokenSource();Check(Reject(()=>c.Save(0,Next("canceled"),false,ct.Token,new Inline(p=>ct.Cancel()))) is OperationCanceledException);Check(!File.Exists(Next("canceled"))&&!Directory.GetDirectories(root).Any());});
Test("I/O failure after chunk cleanup",()=>{Reject(()=>c.Save(0,Next("io-fail"),false,default,new Inline(p=>throw new IOException("dummy injected write failure"))));Check(!File.Exists(Next("io-fail"))&&!Directory.GetDirectories(root).Any());});
Test("delete lock retains original cause and warns path; gate released",()=>{FileStream? locked=null;var ex=Reject(()=>c.Save(0,Next("locked-output"),false,default,new Inline(p=>{string payload=Directory.GetFiles(root,"payload",SearchOption.AllDirectories).Single();new FileInfo(payload).IsReadOnly=true;throw new IOException("ORIGINAL DUMMY");})));Check(ex is PlaintextResidueException&&ex.InnerException!.Message=="ORIGINAL DUMMY"&&ex.Message.Contains("平文")&&ex.Message.Contains(root));string p=Directory.GetFiles(root,"payload",SearchOption.AllDirectories).Single();new FileInfo(p).IsReadOnly=false;Check(SecureAttachment.Recover().Count==0);c.Save(1,Next("gate-released"),false,default);locked?.Dispose();});
Test("batch success counts and name collisions",()=>{string f=Next("batch");Directory.CreateDirectory(f);File.WriteAllText(Path.Combine(f,Path.GetFileName(input)),"KEEP");var r=AttachmentBatch.Save(c,f,default);Check(r.Succeeded==2&&r.Failed==0&&r.Unprocessed==0&&File.ReadAllText(Path.Combine(f,Path.GetFileName(input)))=="KEEP");});
Test("batch cancel preserves completed",()=>{string f=Next("batch-cancel");Directory.CreateDirectory(f);using var ct=new CancellationTokenSource();var r=AttachmentBatch.Save(c,f,ct.Token,new BatchInline(p=>{if(p.Completed==1)ct.Cancel();}));Check(r.Succeeded==1&&r.Unprocessed==1&&r.Canceled);});
Test("batch cleanup failure carries warning",()=>{string f=Next("batch-fail");Directory.CreateDirectory(f);var r=AttachmentBatch.Save(c,f,default,new BatchInline(p=>{var a=Directory.GetFiles(root,"payload",SearchOption.AllDirectories);if(a.Length>0){new FileInfo(a[0]).IsReadOnly=true;throw new IOException("DUMMY BATCH");}}));Check(r.Failed==1&&r.Unprocessed==1&&r.ResidueWarning?.Contains("平文")==true);foreach(string p in Directory.GetFiles(root,"payload",SearchOption.AllDirectories))new FileInfo(p).IsReadOnly=false;SecureAttachment.Recover();});
}
Test("active session recovery protects file",()=>{using var j=SecureAttachment.Create(Next("live"));File.WriteAllText(j.PathName,"DUMMY");Check(SecureAttachment.Recover().Count==0&&File.Exists(j.PathName));j.Finish(null);});
Test("locked leftover recovery warns then succeeds",()=>{var j=SecureAttachment.Create(Next("lock"));string path=j.PathName;File.WriteAllText(path,"DUMMY");j.Dispose();using(var f=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read)){Check(SecureAttachment.Recover().Count==1&&File.Exists(path));}Check(SecureAttachment.Recover().Count==0&&!File.Exists(path));});
Test("replacement identity refuses deletion",()=>{var j=SecureAttachment.Create(Next("id"));string path=j.PathName;File.WriteAllText(path,"OLD");j.Dispose();File.Move(path,path+".old");File.WriteAllText(path,"USER DUMMY");File.Delete(path+".old");Check(SecureAttachment.Recover().Count==1&&File.ReadAllText(path)=="USER DUMMY");});
// Keep identity-mismatch evidence; separate root for subsequent tests.
SetRoot(Next("private2"));
Test("unknown file preserved",()=>{using(var j=SecureAttachment.Create(Next("a")))j.Finish(null);File.WriteAllText(Path.Combine(root,"unknown.tmp"),"USER DUMMY");Check(SecureAttachment.Recover().Count==1&&File.Exists(Path.Combine(root,"unknown.tmp")));});
Test("junction recovery refuses outside data",()=>{string outside=Next("outside");Directory.CreateDirectory(outside);File.WriteAllText(Path.Combine(outside,"keep"),"KEEP");string link=Path.Combine(root,Guid.NewGuid().ToString("N"));var si=new ProcessStartInfo(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"WindowsPowerShell/v1.0/powershell.exe")){UseShellExecute=false,CreateNoWindow=true};si.ArgumentList.Add("-NoProfile");si.ArgumentList.Add("-Command");si.ArgumentList.Add("$ErrorActionPreference='Stop';New-Item -ItemType Junction -Path '"+link.Replace("'","''")+"' -Target '"+outside.Replace("'","''")+"' | Out-Null");using var p=Process.Start(si)!;p.WaitForExit();Check(p.ExitCode==0);Check(SecureAttachment.Recover().Count>=1&&File.ReadAllText(Path.Combine(outside,"keep"))=="KEEP");Directory.Delete(link);});
Test("UNC rejected before plaintext",()=>Check(Reject(()=>SecureAttachment.Create(@"\\invalid\share\out")) is IOException));
Test("different volume override rejected",()=>{SetRoot(@"C:\not-created-cc112");Check(Reject(()=>SecureAttachment.Create(Next("cross"))) is IOException);SetRoot(Next("private3"));});
Test("unsafe preexisting ACL rejected",()=>{string r=Next("unsafe");Directory.CreateDirectory(r);SetRoot(r);Reject(()=>SecureAttachment.Create(Next("unsafe-output")));Check(!Directory.EnumerateFileSystemEntries(r).Any());SetRoot(Next("private3"));});
Test("isolated child crash and recovery",()=>{string child=Next("child");Directory.CreateDirectory(child);var si=new ProcessStartInfo(Environment.ProcessPath!){UseShellExecute=false,CreateNoWindow=true};si.ArgumentList.Add(child);si.ArgumentList.Add("crash");using var p=Process.Start(si)!;for(int i=0;i<100&&!File.Exists(Path.Combine(child,"ready"));i++)Thread.Sleep(100);Check(File.Exists(Path.Combine(child,"ready")));p.Kill();p.WaitForExit();SetRoot(Path.Combine(child,"private"));Check(Directory.GetFiles(root,"payload",SearchOption.AllDirectories).Length==1);Check(SecureAttachment.Recover().Count==0&&!Directory.GetDirectories(root).Any());SetRoot(Next("private3"));});
Test("v1 TEXT and Armor roundtrip",()=>{string f=Next("v1.ccap");C.GenerateCcap(f,"TEXT 😀",BodyKind.TEXT,[],pw,false,default);using var c=C.Unlock(f,pw,default);Check(c.Manifest.Body=="TEXT 😀"&&c.PublicMessageText=="");Check(ArmorMessages.Decrypt(ArmorMessages.Encrypt("Armor 😀",pw,default),pw,default)=="Armor 😀");});
Test("public message tamper rejected",()=>{byte[] b=File.ReadAllBytes(package);b[176]^=1;using var m=new MemoryStream(b);Reject(()=>C.Unlock(m,pw,default));});
Test("attachment authentication rejects tamper",()=>{byte[] b=File.ReadAllBytes(package);b[200]^=1;using var m=new MemoryStream(b);Reject(()=>C.Unlock(m,pw,default));});
Test("INI flags defaults and bounded persisted fields",()=>{var s=new Settings();Check(s.AllowCopy&&!s.ChecksumSHA512&&!s.ChecksumSHA256&&s.OutputFormat==OutputFormat.EXE);s.Save();string ini=File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"CipherCapsule.ini"));Check(!ini.Contains("Password=")&&!ini.Contains("PublicMessage"));});

Test("extra current cleanup cancel and key gate regression",()=>{SetRoot(Next("extra-private"));using var c=C.Unlock(package,pw,default);using var ct=new CancellationTokenSource();Check(Reject(()=>c.Save(0,Next("extra-cancel"),false,ct.Token,new Inline(p=>ct.Cancel()))) is OperationCanceledException);Check(!File.Exists(Next("extra-cancel")));c.Save(1,Next("extra-zero"),false,default);Check(!Directory.GetDirectories(root).Any());});
Test("extra actual sharing lock warning preserves cause",()=>{SetRoot(Next("extra-private"));var j=SecureAttachment.Create(Next("extra-out"));File.WriteAllText(j.PathName,"DUMMY");using(var f=new FileStream(j.PathName,FileMode.Open,FileAccess.Read,FileShare.Read)){var e=Reject(()=>j.Finish(new OperationCanceledException("DUMMY CANCEL")));Check(e is PlaintextResidueException&&e.InnerException is OperationCanceledException&&e.Message.Contains(j.PathName));}j.Finish(null);j.Dispose();Check(!Directory.GetDirectories(root).Any());});
Test("extra invalid HMAC record retained",()=>{SetRoot(Next("extra-private"));var j=SecureAttachment.Create(Next("extra-auth"));File.WriteAllText(j.PathName,"DUMMY");string path=j.PathName;string state=Path.Combine(Path.GetDirectoryName(path)!,"state");j.Dispose();byte[] b=File.ReadAllBytes(state);b[0]^=1;File.WriteAllBytes(state,b);Check(SecureAttachment.Recover().Count==1&&File.Exists(path));SetRoot(Next("extra-private2"));});
Test("extra EXE overlay new template v2 decrypt and save",()=>{string f=Next("extra-message.exe");using var v=File.OpenRead(Path.GetFullPath("templates/CipherCapsule_Viewer.exe"));C.Generate(v,f,"overlay",BodyKind.TEXT,[zero],pw,false,default,publicMessage:"公開");using var c=C.Unlock(f,pw,default);Check(c.PublicMessageText=="公開");c.Save(0,Next("extra-exe-empty"),false,default);Check(new FileInfo(Next("extra-exe-empty")).Length==0);});

Test("repair unsafe Everyone ACL creation rejection",()=>{SetRoot(Next("repair-unsafe"));var a=new DirectorySecurity();var user=WindowsIdentity.GetCurrent().User!;a.SetOwner(user);a.SetAccessRuleProtection(true,false);foreach(var sid in new[]{user,new SecurityIdentifier(WellKnownSidType.LocalSystemSid,null),new SecurityIdentifier(WellKnownSidType.WorldSid,null)})a.AddAccessRule(new FileSystemAccessRule(sid,FileSystemRights.FullControl,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));new DirectoryInfo(root).Create(a);Check(new DirectoryInfo(root).GetAccessControl().GetAccessRules(true,true,typeof(SecurityIdentifier)).Count==3);Reject(()=>SecureAttachment.Create(Next("repair-out")));Check(!Directory.EnumerateFileSystemEntries(root).Any());});
Test("repair auth failure during extraction no final plaintext",()=>{SetRoot(Next("repair-auth"));byte[] b=File.ReadAllBytes(package);using var m=new MemoryStream(b);using var c=C.Unlock(m,pw,default,leaveOpen:true);b[checked((int)c.Manifest.Attachments[0].Offset)+30]^=1;var e=Reject(()=>c.Save(0,Next("repair-bad-auth"),false,default));Check(e is CryptographicException);Check(!File.Exists(Next("repair-bad-auth"))&&!Directory.GetDirectories(root).Any());});
Test("repair destination failure removes plaintext",()=>{SetRoot(Next("repair-io"));using var c=C.Unlock(package,pw,default);string dest=Next("repair-folder");Directory.CreateDirectory(dest);Reject(()=>c.Save(0,dest,false,default));Check(Directory.Exists(dest)&&!Directory.GetDirectories(root).Any());});
File.WriteAllText(Next(filter.Length==0?"results.json":"results-"+filter+".json"),JsonSerializer.Serialize(results,new JsonSerializerOptions{WriteIndented=true}));Environment.ExitCode=results.Any(r=>r.GetType().GetProperty("passed")!.GetValue(r) is false)?1:0;
}}
